export const initialPosts=[{id:'p-me-1',authorId:'me',type:'card',format:'Article',title:'Engineering a modern collaborative workspace for developers.',text:'Six weeks ago we embarked on creating Collobster. Here is what we learned connecting real-time feeds, chat channels, and modular spaces into one unified platform.',image:photos.desk,imageAlt:'Minimalist developer workstation with laptop and notebook',category:'Architecture',tags:['React','Engineering','Design'],likes:56,comments:11,createdAt:'2026-09-18T11:00:00Z',body:['We started by mapping out communication friction between builders and designers.','Every tool was isolated—now feeds, projects, and messaging exist in a single place.','Focus on clarity, rapid feedback, and delightful micro-interactions.']},{id:'p-me-2',authorId:'me',type:'poll',format:'Poll',title:'Which stack are you picking for your next project in 2026?',text:'Curious what fellow builders are standardizing on this quarter.',options:['React 19 & Next.js','Flutter 3 & Dart','Go & Microservices','FastAPI & Python'],votes:[28,19,14,8],tags:['React','Flutter','Development'],likes:43,comments:8,createdAt:'2026-09-18T09:30:00Z'},{id:'p-me-3',authorId:'me',type:'achievement',format:'Achievement',title:'Milestone: 1,000 active community members reached! 🎉',text:'Massive milestone today! We hit 1,000 collaborative builders active in the network. Huge gratitude to every mentor, developer, and designer contributing.',image:photos.event,imageAlt:'Celebration event with builders and mentors',tags:['Milestone','Community','Achievement'],likes:95,comments:16,createdAt:'2026-09-17T15:45:00Z'},{id:'p-me-4',authorId:'me',type:'project',format:'Project',title:'Open Collaboration Workspace Core',text:'We are building an open-source collaboration hub with real-time sync, reactive feeds, and verified mentor spaces. Looking for backend and frontend contributors.',tags:['Open source','Projects','React'],likes:37,comments:5,createdAt:'2026-09-16T18:20:00Z'},{id:'p-me-5',authorId:'me',type:'post',format:'Post',text:'Just pushed a performance update to our state pipeline. Memory footprint dropped by 35% and feed filtering is now instantaneous! Always measure before and after optimizing.',tags:['Performance','WebDev'],likes:29,comments:3,createdAt:'2026-09-16T14:10:00Z'},{id:'p1',authorId:'riya',type:'card',format:'Article',title:'Good things happen when we build together.',text:'Six strangers. One weekend. A little courage to put an idea out there. Here is what we learned building our first community project.',image:photos.team,imageAlt:'A team collaborating on a project around a table',category:'Build in public',tags:['Design','Projects'],likes:128,comments:18,createdAt:'2026-09-17T09:00:00Z',body:['We started with a shared problem, not a shared skill set. Everyone had felt the frustration of finding collaborators who cared about the same things.','Our first hour was spent listening. We wrote down assumptions, drew rough ideas, and agreed on one small thing we could finish before Sunday.','The most useful lesson was to make the work visible. A short update, a clear next step, and an invitation to contribute did more than a perfect plan ever could.','If you are waiting until your idea feels ready, try sharing the question instead. Your next collaborator might be working on the same one.']},{id:'p2',authorId:'aman',type:'post',format:'Post',text:'A small win today: shipped my first Flutter package! It makes offline-first forms a little less painful.\n\nLooking for a couple of developers to try it out and give honest feedback. Anyone building something with Flutter?',tags:['Flutter','Open source'],likes:64,comments:12,createdAt:'2026-09-17T07:30:00Z'},{id:'p3',authorId:'neha',type:'project',format:'Project',title:'A fresher way to connect local farms and families.',text:'We are building GreenCart, a community-led local produce network. Looking for a React developer and a product designer who care about sustainable food.',tags:['React','Climate','Projects'],likes:42,comments:7,createdAt:'2026-09-16T16:00:00Z'},{id:'p4',authorId:'arjun',type:'poll',format:'Poll',title:'What is your next learning goal?',text:'Curious about what everyone is focusing on this month.',options:['Ship a real project','Learn a new stack','Find a mentor','Build my network'],votes:[42,28,19,11],tags:['Learning','Career'],likes:31,comments:4,createdAt:'2026-09-16T12:00:00Z'}];
